style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("web.roblox.com") {
:root { --accent:#ff1a2a; --bg:#0b0b0c; }
  html, body { background:var(--bg) !important; color:#ff1a2a !important; font-family:ui-monospace,Consolas,Menlo,monospace !important; }

  /* 아이콘(SVG)까지 빨강 */
  svg, svg *, i, .icon { fill:var(--accent) !important; stroke:var(--accent) !important; color:var(--accent) !important; }

  /* 카드/패널 배경 다크 */
  .container, .content, .section, .card, .rbx-card, .modal-content, .dropdown-menu {
    background:#16161c !important; border:1px solid rgba(255,26,42,.25) !important;
  }

  /* 버튼 */
  .btn, button, [role="button"], .rbx-btn {
    background:linear-gradient(180deg, var(--accent), #b3121d) !important;
    color:#fff !important; border:1px solid rgba(255,26,42,.6) !important;
  }

  /* 링크 */
  a { color:var(--accent) !important; }
  a:hover { text-decoration:underline wavy rgba(255,26,42,.6) 1px !important; }

  /* 입력 */
  input, textarea, select { background:#0e0e14 !important; color:#ff1a2a !important; border:1px solid rgba(255,26,42,.35) !important; }
}
